import React, { useState } from "react";
import { ethers } from "ethers";
import { getContract } from "../utils/blockchain";

export default function MintTicket() {
  const [loading, setLoading] = useState(false);
  const [status, setStatus] = useState("");

  async function handleMint() {
    try {
      setLoading(true);
      setStatus("Minting ticket...");
      const contract = await getContract();
      // Contoh mint dengan eventDate 7 hari ke depan, expire 10 hari ke depan, max resale price 0.1 ETH
      const eventDate = Math.floor(Date.now() / 1000) + 7 * 24 * 3600;
      const expirationDate = Math.floor(Date.now() / 1000) + 10 * 24 * 3600;
      const maxResalePrice = ethers.utils.parseEther("0.1");

      const tx = await contract.mintTicket(
        await contract.signer.getAddress(),
        eventDate,
        expirationDate,
        maxResalePrice
      );
      await tx.wait();

      setStatus("Ticket minted successfully!");
    } catch (err) {
      setStatus("Error minting ticket: " + err.message);
    } finally {
      setLoading(false);
    }
  }

  return (
    <div style={{ marginTop: 20 }}>
      <h3>Mint Event Ticket</h3>
      <button onClick={handleMint} disabled={loading}>
        {loading ? "Minting..." : "Mint Ticket"}
      </button>
      <p>{status}</p>
    </div>
  );
}
